// Command structure
typedef struct {
    uint8_t motor_id;
    uint8_t command_type;
    int32_t value;
    uint8_t data[32];
    uint8_t data_length;
} Command;

// Motor state
typedef enum {
    MOTOR_STATE_IDLE = 0,
    MOTOR_STATE_ENABLED,
    MOTOR_STATE_RUNNING,
    MOTOR_STATE_FAULT,
    MOTOR_STATE_DISABLED,
    MOTOR_STATE_POSITION_CONTROL,
    MOTOR_STATE_VELOCITY_CONTROL,
    MOTOR_STATE_TORQUE_CONTROL
} MotorState;

// PID Controller
typedef struct {
    float kp, ki, kd;
    float integral;
    float derivative;
    float output;
    float setpoint;
    float error;
    float prev_error;

    void reset() {
        integral = 0;
        derivative = 0;
        output = 0;
        prev_error = 0;
    }

    float compute(float setpoint, float measurement) {
        error = setpoint - measurement;
        integral += error;
        derivative = error - prev_error;
        output = kp * error + ki * integral + kd * derivative;
        prev_error = error;
        return output;
    }
} PIDController;

